package com.yesbee.nwtrack.production;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.yesbee.nwtrack.routing.RouteDerivationService;
import com.yesbee.nwtrack.shared.BusinessRuleException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.*;

@Service
public class StyleRevisionService {
    public enum Scope { UNSTARTED, ALL_IN_PROGRESS }
    private final JdbcTemplate jdbc;private final RouteDerivationService routes;private final ObjectMapper json;
    public StyleRevisionService(JdbcTemplate jdbc,RouteDerivationService routes,ObjectMapper json){this.jdbc=jdbc;this.routes=routes;this.json=json;}

    @Transactional
    public RevisionResult revise(UUID styleId,String description,List<UUID> processIds,Integer quantity,String reason,Scope scope,UUID actor,String actorRole){
        if(processIds==null||processIds.isEmpty())throw new BusinessRuleException("STYLE_PROCESSES_REQUIRED","A Style revision requires at least one Process");
        Map<String,Object> style=jdbc.queryForMap("select id,style_number,description,status,version from styles where id=? for update",styleId);
        List<Map<String,Object>> beforeTemplate=template(styleId);
        List<UUID> lots=scope==Scope.UNSTARTED
                ?jdbc.query("select l.id from lots l where l.style_id=? and l.status='READY' and not exists(select 1 from process_executions pe join station_visits sv on sv.id=pe.station_visit_id where sv.lot_id=l.id and pe.started_at is not null) order by l.created_at for update",(rs,n)->(UUID)rs.getObject(1),styleId)
                :jdbc.query("select id from lots where style_id=? and status not in ('READY','COMPLETED','CANCELLED') order by created_at for update",(rs,n)->(UUID)rs.getObject(1),styleId);
        if(scope==Scope.ALL_IN_PROGRESS){Integer transit=jdbc.queryForObject("select count(*) from lots where style_id=? and status='DISPATCHED'",Integer.class,styleId);if(transit!=null&&transit>0)throw new BusinessRuleException("ROUTE_EDIT_BLOCKED_IN_TRANSIT","Receive every dispatched Lot before changing the in-progress route");}
        replaceTemplate(styleId,processIds);
        List<RouteDerivationService.RouteEntry> route=derive(styleId);
        validateQc(route);
        buildStyleRoute(styleId,route);
        if(description!=null)jdbc.update("update styles set description=?,version=version+1 where id=?",description,styleId);else jdbc.update("update styles set version=version+1 where id=?",styleId);
        List<Map<String,Object>> afterTemplate=template(styleId);
        int revision=Optional.ofNullable(jdbc.queryForObject("select max(revision_no) from style_revisions where style_id=?",Integer.class,styleId)).orElse(0)+1;
        UUID revisionId=UUID.randomUUID();
        jdbc.update("insert into style_revisions(id,style_id,revision_no,actor_id,actor_role,reason,before_snapshot,after_snapshot,affected_lot_count) values (?,?,?,?,?,?,?::jsonb,?::jsonb,?)",revisionId,styleId,revision,actor,actorRole,reason,toJson(beforeTemplate),toJson(afterTemplate),lots.size());
        for(UUID lot:lots){List<Map<String,Object>> before=lotSnapshot(lot);if(scope==Scope.UNSTARTED)rebuildUnstarted(lot,route);else reviseInProgress(lot,route,actor,reason);if(quantity!=null)changeQuantity(lot,quantity,actor,reason);List<Map<String,Object>> after=lotSnapshot(lot);int lotRevision=Optional.ofNullable(jdbc.queryForObject("select max(revision_no) from lot_route_revisions where lot_id=?",Integer.class,lot)).orElse(0)+1;jdbc.update("insert into lot_route_revisions(id,style_revision_id,lot_id,revision_no,before_snapshot,after_snapshot) values (?,?,?,?,?::jsonb,?::jsonb)",UUID.randomUUID(),revisionId,lot,lotRevision,toJson(before),toJson(after));queueNotification(lot,revisionId,reason);}
        jdbc.update("insert into audit_log(actor_id,action,object_type,object_id,outcome,reason,detail) values (?,'STYLE_REVISION','STYLE',?,'SUCCESS',?,jsonb_build_object('scope',?,'affectedLots',?,'revision',?))",actor,styleId,reason,scope.name(),lots.size(),revision);
        return new RevisionResult(revisionId,revision,lots.size(),scope);
    }

    private void replaceTemplate(UUID styleId,List<UUID> processIds){jdbc.update("delete from style_route_entries where style_id=?",styleId);jdbc.update("delete from style_processes where style_id=?",styleId);int seq=1;for(UUID p:processIds)jdbc.update("insert into style_processes(id,style_id,process_id,sequence_no) values (?,?,?,?)",UUID.randomUUID(),styleId,p,seq++);}
    private List<RouteDerivationService.RouteEntry> derive(UUID styleId){return routes.derive(jdbc.query("select p.id,p.code,sp.sequence_no,p.station_id,s.code from style_processes sp join processes p on p.id=sp.process_id join stations s on s.id=p.station_id where sp.style_id=? and p.active and s.active order by sp.sequence_no",(rs,n)->new RouteDerivationService.SelectedProcess((UUID)rs.getObject(1),rs.getString(2),rs.getInt(3),(UUID)rs.getObject(4),rs.getString(5)),styleId));}
    private void validateQc(List<RouteDerivationService.RouteEntry> route){if(route.isEmpty())throw new BusinessRuleException("EMPTY_ROUTE","Style route is empty");Boolean qc=jdbc.queryForObject("select is_qc from stations where id=?",Boolean.class,route.getLast().stationId());if(!Boolean.TRUE.equals(qc))throw new BusinessRuleException("QC_MUST_BE_LAST","The final Station must be QC");}
    private void buildStyleRoute(UUID styleId,List<RouteDerivationService.RouteEntry> route){for(var entry:route){UUID routeId=UUID.randomUUID();jdbc.update("insert into style_route_entries(id,style_id,station_id,sequence_no) values (?,?,?,?)",routeId,styleId,entry.stationId(),entry.sequence());int local=1;for(var p:entry.processes()){UUID sp=jdbc.queryForObject("select id from style_processes where style_id=? and process_id=?",UUID.class,styleId,p.processId());jdbc.update("insert into style_route_processes(route_entry_id,style_process_id,sequence_no) values (?,?,?)",routeId,sp,local++);}}}
    private void rebuildUnstarted(UUID lot,List<RouteDerivationService.RouteEntry> route){jdbc.update("delete from station_visits where lot_id=?",lot);jdbc.update("delete from lot_route_entries where lot_id=?",lot);appendRoute(lot,route,1,null);jdbc.update("update lots set current_route_sequence=1,status='READY',version=version+1 where id=?",lot);}
    private void reviseInProgress(UUID lot,List<RouteDerivationService.RouteEntry> route,UUID actor,String reason){Integer max=jdbc.queryForObject("select coalesce(max(sequence_no),0) from lot_route_entries where lot_id=?",Integer.class,lot);UUID currentStation=jdbc.queryForObject("select station_id from station_visits where lot_id=? and lot_route_entry_id=(select id from lot_route_entries where lot_id=? and sequence_no=(select current_route_sequence from lots where id=?))",UUID.class,lot,lot,lot);Set<UUID> completed=new HashSet<>(jdbc.query("select distinct pe.process_id from process_executions pe join station_visits sv on sv.id=pe.station_visit_id where sv.lot_id=? and pe.status='COMPLETED'",(rs,n)->(UUID)rs.getObject(1),lot));jdbc.update("update process_executions set status='SKIPPED',completed_at=coalesce(completed_at,now()),operator_id=?,reason=?,version=version+1 where station_visit_id in(select id from station_visits where lot_id=?) and status not in ('COMPLETED','SKIPPED')",actor,"Superseded by Manager route revision: "+reason,lot);int first=appendRoute(lot,route,max+1,completed);UUID nextStation=jdbc.queryForObject("select station_id from lot_route_entries where lot_id=? and sequence_no=?",UUID.class,lot,first);if(nextStation.equals(currentStation)){jdbc.update("update station_visits set status='RECEIVED',received_at=now(),received_by=? where lot_id=? and lot_route_entry_id=(select id from lot_route_entries where lot_id=? and sequence_no=?)",actor,lot,lot,first);jdbc.update("update lots set current_route_sequence=?,status='AT_STATION',current_location_type='PROCESS_AREA',current_location_id=?,version=version+1 where id=?",first,currentStation,lot);}else jdbc.update("update lots set current_route_sequence=?,status='READY_FOR_DISPATCH',version=version+1 where id=?",first-1,lot);}
    private int appendRoute(UUID lot,List<RouteDerivationService.RouteEntry> route,int start,Set<UUID> completed){int seq=start,first=-1;for(var entry:route){List<RouteDerivationService.SelectedProcess> pending=completed==null?entry.processes():entry.processes().stream().filter(p->!completed.contains(p.processId())).toList();if(pending.isEmpty())continue;UUID lr=UUID.randomUUID(),visit=UUID.randomUUID();if(first<0)first=seq;jdbc.update("insert into lot_route_entries(id,lot_id,station_id,sequence_no,status) values (?,?,?,?,'EXPECTED')",lr,lot,entry.stationId(),seq++);jdbc.update("insert into station_visits(id,lot_id,lot_route_entry_id,station_id,status) values (?,?,?,?,'EXPECTED')",visit,lot,lr,entry.stationId());int pseq=1;for(var p:pending)jdbc.update("insert into process_executions(id,station_visit_id,process_id,sequence_no,status) values (?,?,?,?,'PENDING')",UUID.randomUUID(),visit,p.processId(),pseq++);}if(first<0)throw new BusinessRuleException("NO_PENDING_ROUTE","Revised route contains no pending work for the Lot");return first;}
    private void changeQuantity(UUID lot,int quantity,UUID actor,String reason){if(quantity<=0)throw new BusinessRuleException("INVALID_QUANTITY","Lot quantity must be positive");Integer old=jdbc.queryForObject("select quantity from lots where id=?",Integer.class,lot);if(old!=null&&old!=quantity){jdbc.update("insert into lot_quantity_changes(lot_id,old_quantity,new_quantity,actor_id,reason) values (?,?,?,?,?)",lot,old,quantity,actor,reason);jdbc.update("update lots set quantity=?,version=version+1 where id=?",quantity,lot);}}
    private void queueNotification(UUID lot,UUID revision,String reason){Map<String,Object> row=jdbc.queryForMap("select l.lot_number,l.current_route_sequence,lr.station_id from lots l join lot_route_entries lr on lr.lot_id=l.id and lr.sequence_no=l.current_route_sequence where l.id=?",lot);Map<String,Object> payload=new LinkedHashMap<>();payload.put("lotId",lot);payload.put("lotNumber",row.get("lot_number"));payload.put("destinationStationId",row.get("station_id"));payload.put("styleRevisionId",revision);payload.put("reason",reason);jdbc.update("insert into outbox_events(id,aggregate_type,aggregate_id,aggregate_version,event_type,payload) values (?,'LOT',?,1,'STYLE_ROUTE_CHANGED',?::jsonb)",UUID.randomUUID(),lot,toJson(payload));}
    private List<Map<String,Object>> template(UUID style){return jdbc.queryForList("select sp.sequence_no,p.id process_id,p.code,p.name,p.station_id from style_processes sp join processes p on p.id=sp.process_id where sp.style_id=? order by sp.sequence_no",style);}
    private List<Map<String,Object>> lotSnapshot(UUID lot){return jdbc.queryForList("select lr.sequence_no route_sequence,lr.station_id,lr.status route_status,pe.id execution_id,pe.process_id,pe.sequence_no process_sequence,pe.status process_status from lot_route_entries lr join station_visits sv on sv.lot_route_entry_id=lr.id left join process_executions pe on pe.station_visit_id=sv.id where lr.lot_id=? order by lr.sequence_no,pe.sequence_no",lot);}
    private String toJson(Object value){try{return json.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalStateException(e);}}
    public record RevisionResult(UUID revisionId,int revisionNumber,int affectedLots,Scope scope){}
}
